div.script:
(function() {
    var btn = document.getElementById('hubCalBtn');
    var pop = document.getElementById('hubCalPopover');
    var prevBtn = document.getElementById('hubCalPrev');
    var nextBtn = document.getElementById('hubCalNext');
    var monthLbl = document.getElementById('hubCalMonthLabel');
    var grid = document.getElementById('hubCalGrid');
    var textFrom = document.getElementById('hubTextFrom');
    var textTo = document.getElementById('hubTextTo');
    var boxFrom = document.getElementById('hubBoxFrom');
    var boxTo = document.getElementById('hubBoxTo');
    var btnCancel = document.getElementById('hubCalCancel');
    var btnApply = document.getElementById('hubCalApply');

    if (!btn || !pop) return;

    var initialStart = "";
    var initialEnd = "";
    var basePath = "";
    var extraParams = {


                "": "",


    };

    var isCustomRange = "" === "1";
    var fromDate = initialStart ? new Date(initialStart + 'T00:00:00') : null;
    var toDate = (isCustomRange && initialEnd) ? new Date(initialEnd + 'T00:00:00') : null;
    var activeTarget = toDate ? 'from' : (fromDate ? 'to' : 'from');
    var viewDate = fromDate ? new Date(fromDate) : new Date();

    function formatDateDisplay(d) {
        if (!d) return '--';
        var dd = String(d.getDate()).padStart(2, '0');
        var mm = String(d.getMonth() + 1).padStart(2, '0');
        var yyyy = d.getFullYear();
        return dd + '-' + mm + '-' + yyyy;
    }

    function formatDateParam(d) {
        if (!d) return '';
        var dd = String(d.getDate()).padStart(2, '0');
        var mm = String(d.getMonth() + 1).padStart(2, '0');
        var yyyy = d.getFullYear();
        return yyyy + '-' + mm + '-' + dd;
    }

    var monthNames = ["January","February","March","April","May","June","July","August","September","October","November","December"];

    function renderInputs() {
        textFrom.textContent = formatDateDisplay(fromDate);
        textTo.textContent = formatDateDisplay(toDate);
        if (activeTarget === 'from') {
            boxFrom.classList.add('active');
            boxTo.classList.remove('active');
        } else {
            boxTo.classList.add('active');
            boxFrom.classList.remove('active');
        }
    }

    function renderCalendar() {
        monthLbl.textContent = monthNames[viewDate.getMonth()] + ' ' + viewDate.getFullYear();
        // Clear existing day cells, keep only first 7 weekday items
        while (grid.children.length > 7) {
            grid.removeChild(grid.lastChild);
        }

        var year = viewDate.getFullYear();
        var month = viewDate.getMonth();
        var firstDay = new Date(year, month, 1);
        var lastDay = new Date(year, month + 1, 0);

        // Mo=0, Su=6
        var startDayOfWeek = (firstDay.getDay() + 6) % 7;
        var daysInMonth = lastDay.getDate();

        // Previous month pad
        var prevMonthLastDay = new Date(year, month, 0).getDate();
        for (var p = startDayOfWeek - 1; p >= 0; p--) {
            var cell = document.createElement('div');
            cell.className = 'hub-cal-day-cell other-month';
            var span = document.createElement('span');
            span.className = 'hub-cal-day';
            span.textContent = prevMonthLastDay - p;
            cell.appendChild(span);
            grid.appendChild(cell);
        }

        // Month days
        for (var d = 1; d <= daysInMonth; d++) {
            var thisDate = new Date(year, month, d);
            var cell = document.createElement('div');
            cell.className = 'hub-cal-day-cell';

            var isStart = fromDate && thisDate.toDateString() === fromDate.toDateString();
            var isEnd = toDate && thisDate.toDateString() === toDate.toDateString();
            var inRange = fromDate && toDate && thisDate > fromDate && thisDate < toDate;

            if (isStart || isEnd) cell.classList.add('selected');
            if (isStart) cell.classList.add('range-start');
            if (isEnd) cell.classList.add('range-end');
            if (inRange) cell.classList.add('in-range');

            var span = document.createElement('span');
            span.className = 'hub-cal-day';
            span.textContent = d;
            cell.appendChild(span);

            (function(dateObj) {
                cell.addEventListener('click', function(e) {
                    e.stopPropagation();
                    var clickedTime = dateObj.getTime();

                    if (activeTarget === 'from') {
                        if (toDate && clickedTime > toDate.getTime()) {
                            // User clicked a date after 'to', so this becomes 'to'
                            toDate = new Date(dateObj);
                            activeTarget = 'from';
                        } else {
                            fromDate = new Date(dateObj);
                            activeTarget = toDate ? 'from' : 'to';
                        }
                    } else { // activeTarget === 'to'
                        if (fromDate && clickedTime < fromDate.getTime()) {
                            // User clicked a date before 'from', so this becomes 'from'
                            fromDate = new Date(dateObj);
                            activeTarget = 'to';
                        } else {
                            toDate = new Date(dateObj);
                            activeTarget = 'to';
                        }
                    }
                    renderInputs();
                    renderCalendar();
                });
            })(thisDate);

            grid.appendChild(cell);
        }
    }

    btn.addEventListener('click', function(e) {
        e.stopPropagation();
        var isOpen = pop.classList.contains('open');
        if (isOpen) {
            pop.classList.remove('open');
            btn.classList.remove('active');
        } else {
            pop.classList.add('open');
            btn.classList.add('active');
            renderInputs();
            renderCalendar();
        }
    });

    boxFrom.addEventListener('click', function(e) {
        e.stopPropagation();
        activeTarget = 'from';
        renderInputs();
    });

    boxTo.addEventListener('click', function(e) {
        e.stopPropagation();
        activeTarget = 'to';
        renderInputs();
    });

    prevBtn.addEventListener('click', function(e) {
        e.stopPropagation();
        viewDate = new Date(viewDate.getFullYear(), viewDate.getMonth() - 1, 1);
        renderCalendar();
    });

    nextBtn.addEventListener('click', function(e) {
        e.stopPropagation();
        viewDate = new Date(viewDate.getFullYear(), viewDate.getMonth() + 1, 1);
        renderCalendar();
    });

    btnCancel.addEventListener('click', function(e) {
        e.stopPropagation();
        pop.classList.remove('open');
        btn.classList.remove('active');
        fromDate = initialStart ? new Date(initialStart + 'T00:00:00') : null;
        toDate = (isCustomRange && initialEnd) ? new Date(initialEnd + 'T00:00:00') : null;
        activeTarget = toDate ? 'from' : (fromDate ? 'to' : 'from');
        renderInputs();
        renderCalendar();
    });

    btnApply.addEventListener('click', function(e) {
        e.stopPropagation();
        var params = new URLSearchParams();
        for (var k in extraParams) {
            if (extraParams[k]) params.append(k, extraParams[k]);
        }
        if (fromDate) params.append('date_from', formatDateParam(fromDate));
        if (toDate) params.append('date_to', formatDateParam(toDate));
        var qs = params.toString();
        window.location.href = basePath + (qs ? ('?' + qs) : '');
    });

    document.addEventListener('click', function(e) {
        if (!pop.contains(e.target) && e.target !== btn && !btn.contains(e.target)) {
            pop.classList.remove('open');
            btn.classList.remove('active');
        }
    });
})();

t.script:
(function() {
    var searchInput = document.getElementById('stockSearchInput');
    var searchBtn = document.getElementById('stockSearchBtn');
    var table = document.getElementById('stockCountTable');
    if (!searchInput || !table) return;

    function doFilter() {
        var query = searchInput.value.toLowerCase().trim();
        var rows = table.querySelectorAll('tbody tr.stock-row');
        rows.forEach(function(row) {
            var name = row.querySelector('.product-name') ? row.querySelector('.product-name').textContent.toLowerCase() : '';
            if (!query || name.indexOf(query) !== -1) {
                row.style.display = '';
            } else {
                row.style.display = 'none';
            }
        });
    }

    searchInput.addEventListener('input', doFilter);
    if (searchBtn) searchBtn.addEventListener('click', doFilter);
})();
